#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

// SROD1 - Rod element stress recovery (phase I)
// Translated from NASTRAN-95 Fortran 77.

int main() {
    // ---- Test case inputs ----
    const double L      = 2.0;
    const double A      = 0.01;
    const double E      = 2.1e11;
    const double nu     = 0.3;
    const double J      = 5e-6;
    const double C      = 0.005;   // J / max_radius

    // Node displacements (6 DOF each): pure axial
    // node_a = (0,0,0,0,0,0), node_b = (0.001,0,0,0,0,0)
    Eigen::Matrix<double,6,1> ua, ub;
    ua.setZero();
    ub.setZero();
    ub(0) = 0.001;

    // ---- Geometry: rod along x-axis ----
    // Node coordinates
    Eigen::Vector3d pa(0.0, 0.0, 0.0);
    Eigen::Vector3d pb(L,   0.0, 0.0);

    // Vector along rod, length, normalize
    Eigen::Vector3d XN = pb - pa;
    double XL = XN.norm();
    XN /= XL;

    double EOVERL = E / XL;

    // Shear modulus
    double G = E / (2.0 * (1.0 + nu));

    // GCOVRL = G * J / (XL * C)  ... but Fortran uses ECPT(6) which is C
    // In the Fortran: GCOVRL = G * ECPT(6) / XL, where ECPT(6) is the
    // torsional constant (here C = J/max_radius).
    double GCOVRL = G * C / XL;

    // ---- Axial force and stress ----
    // Axial strain from relative axial displacement along rod axis
    double delta_axial = (ub - ua).dot(XN);   // = 0.001
    double axial_strain = delta_axial / XL;
    double axial_stress = E * axial_strain;
    double axial_force  = axial_stress * A;

    // ---- Torsional stress ----
    // Relative rotation about rod axis
    Eigen::Vector3d ra(ua(3), ua(4), ua(5));
    Eigen::Vector3d rb(ub(3), ub(4), ub(5));
    double dtheta = (rb - ra).dot(XN);   // = 0
    // Torsional shear stress = G * (dtheta / L) * C
    double torsional_stress = G * (dtheta / XL) * C;

    // ---- Output JSON ----
    std::cout << std::scientific << std::setprecision(6);
    std::cout << "{\"test\":\"SROD1\","
              << "\"axial_stress\":" << axial_stress << ","
              << "\"axial_force\":"  << axial_force  << ","
              << "\"torsional_stress\":" << torsional_stress
              << "}" << std::endl;

    return 0;
}
